const u = $input.first().json;
const msg = u.message || u.edited_message || null;
const cb = u.callback_query || null;
const chatId = (msg && msg.chat && msg.chat.id) || (cb && cb.message && cb.message.chat && cb.message.chat.id) || 0;
const updateId = u.update_id || 0;
const rawText = (msg && typeof msg.text === 'string') ? msg.text : '';
const cbData = (cb && cb.data) ? cb.data : '';
return [{ json: { chatId: chatId, updateId: updateId, text: rawText, cbData: cbData } }];

const p = $('Preparar').first().json;
const key = 'nodo:dedup:' + p.updateId;
let c = $json[key];
if (c == null) { const ns = Object.values($json).filter(v => typeof v === 'number'); c = ns.length ? ns[ns.length - 1] : 1; }
return [{ json: Object.assign({}, p, { dupCount: Number(c) }) }];

const p = $('Preparar').first().json;
const key = 'nodo:rl:' + p.chatId;
let c = $json[key];
if (c == null) { const ns = Object.values($json).filter(v => typeof v === 'number'); c = ns.length ? ns[ns.length - 1] : 1; }
return [{ json: Object.assign({}, p, { rlCount: Number(c) }) }];

const SUPABASE_BASE = 'https://YOUR-PROJECT.supabase.co';
const NL = String.fromCharCode(10);
const stripAccents = (t) => { const d = (t == null ? '' : String(t)).toLowerCase().normalize('NFD'); let r = ''; for (let i = 0; i < d.length; i++) { const c = d.charCodeAt(i); if (c < 768 || c > 879) r += d[i]; } return r.trim(); };
const ctx = $json;
const chatId = ctx.chatId;
const rawText = ctx.text || '';
const cbData = ctx.cbData || '';
const text = stripAccents(rawText);
let base = SUPABASE_BASE; while (base.endsWith('/')) base = base.slice(0, -1);
const R = base + '/rest/v1/';
const urls = {
  persons: R + 'persons?select=id,first_name,last_name,approximate_age,current_status,is_found,city,sector,last_known_address&limit=200',
  shelters: R + 'shelters?status=eq.active&select=id,name,address_text,city,capacity,current_occupancy&order=created_at.desc&limit=40',
  hospitals: R + 'points_of_interest?poi_type=in.(hospital,medical_center)&is_active=eq.true&select=id,name,city,address_text,metadata&limit=40',
  health: R + 'points_of_interest?poi_type=eq.health_request&is_active=eq.true&select=id,name,city,address_text,metadata&order=created_at.desc&limit=40',
  acopio: R + 'points_of_interest?poi_type=eq.collection_center&is_active=eq.true&select=id,name,city,address_text&limit=40',
  campaigns: R + 'official_campaigns?status=eq.active&select=id,title,campaign_type,organization,start_date,end_date&limit=30',
  info: R + 'verified_info?is_active=eq.true&select=id,title,content,category,source,is_pinned&order=is_pinned.desc&limit=15'
};
const BLOODS = ['o+','o-','a+','a-','b+','b-','ab+','ab-'];
const findBlood = () => { const t = text.split(' ').join(''); for (const b of BLOODS) { if (t.indexOf(b) !== -1) return b.toUpperCase(); } return ''; };
const out = (o) => [{ json: Object.assign({ chatId: chatId }, o) }];
if (cbData) {
  if (cbData === 'menu') return out({ mode: 'reply', replyText: 'Que necesitas? Elige una opcion abajo.' });
  if (cbData === 'cat:persons') return out({ mode: 'reply', replyText: 'Escribeme el <b>nombre y apellido</b> de la persona que buscas.' });
  if (cbData === 'cat:health') return out({ mode: 'reply', replyText: 'Escribe el <b>tipo de sangre</b> que se necesita (ej: O+), o la palabra sangre para ver todas.' });
  if (cbData === 'cat:shelters') return out({ mode: 'search', category: 'shelters', query: '', supabaseUrl: urls.shelters });
  if (cbData === 'cat:hospitals') return out({ mode: 'search', category: 'hospitals', query: '', supabaseUrl: urls.hospitals });
  if (cbData === 'cat:acopio') return out({ mode: 'search', category: 'acopio', query: '', supabaseUrl: urls.acopio });
  if (cbData === 'cat:campaigns') return out({ mode: 'search', category: 'campaigns', query: '', supabaseUrl: urls.campaigns });
  if (cbData === 'cat:info') return out({ mode: 'search', category: 'info', query: '', supabaseUrl: urls.info });
}
const isGreeting = (!text || text === '/start' || text === 'start' || text === 'help' || text.indexOf('hola') === 0 || text.indexOf('buenas') === 0 || text.indexOf('menu') === 0 || text.indexOf('ayuda') === 0 || text.indexOf('inicio') === 0);
if (isGreeting) return out({ mode: 'reply', replyText: 'Bienvenido a <b>NODO</b>. Te ayudo a buscar informacion verificada en la emergencia.' + NL + NL + 'Elige una opcion abajo, o escribeme directamente (ej: busco a Maria Gonzalez).' });
const RULES = [
  { cat: 'persons', url: urls.persons, kw: ['busco a','buscar a','desaparecid','se busca','no aparece','no encuentro','donde esta','mi mama','mi papa','mi hijo','mi hija','mi hermano','mi hermana','mi esposo','mi esposa','familiar','perdido','perdida'] },
  { cat: 'health', url: urls.health, kw: ['sangre','donante','donar sangre','banco de sangre','plaquetas','tipo de sangre','transfusion'] },
  { cat: 'hospitals', url: urls.hospitals, kw: ['hospital','clinica','centro medico','medico','emergencia medica','herido','herida','ambulancia'] },
  { cat: 'shelters', url: urls.shelters, kw: ['refugio','albergue','donde dormir','alojamiento','donde ir','quedarme','no tengo donde'] },
  { cat: 'acopio', url: urls.acopio, kw: ['acopio','centro de acopio','donar ropa','donar comida','donaciones','punto de entrega','donde donar','llevar donaciones'] },
  { cat: 'campaigns', url: urls.campaigns, kw: ['campana','jornada','vacunacion','jornada medica','evento','actividad'] },
  { cat: 'info', url: urls.info, kw: ['informacion','info oficial','comunicado','que esta pasando','noticias','alertas','vias cerradas','servicios'] }
];
let best = null;
for (const r of RULES) { let s = 0; for (const k of r.kw) { if (text.indexOf(stripAccents(k)) !== -1) s += k.length; } if (s > 0 && (!best || s > best.score)) best = { cat: r.cat, url: r.url, score: s }; }
const blood = findBlood();
if (blood && (!best || best.cat === 'health')) { return out({ mode: 'search', category: 'health', query: blood, supabaseUrl: urls.health }); }
let q = rawText.trim();
const lower = stripAccents(q);
const prefixes = ['busco a ','buscar a ','se busca a ','se busca ','encontre a ','donde esta ','no encuentro a '];
for (const pre of prefixes) { if (lower.indexOf(pre) === 0) { q = q.slice(pre.length).trim(); break; } }
if (best) { const query = best.cat === 'persons' ? q : (best.cat === 'health' ? blood : ''); return out({ mode: 'search', category: best.cat, query: query, supabaseUrl: best.url }); }
const parts = rawText.trim().split(' ').filter(Boolean);
let looksName = parts.length >= 1 && parts.length <= 4;
if (looksName) { for (const part of parts) { for (const ch of stripAccents(part)) { if (ch < 'a' || ch > 'z') { looksName = false; break; } } if (!looksName) break; } }
if (looksName) return out({ mode: 'search', category: 'persons', query: rawText.trim(), supabaseUrl: urls.persons });
return out({ mode: 'reply', replyText: 'No te entendi bien. Elige una opcion del menu, o escribe el <b>nombre</b> de la persona que buscas.' });

const NL = String.fromCharCode(10);
const esc = (s) => (s == null ? '' : String(s)).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const stripAccents = (t) => { const d = (t == null ? '' : String(t)).toLowerCase().normalize('NFD'); let r = ''; for (let i = 0; i < d.length; i++) { const c = d.charCodeAt(i); if (c < 768 || c > 879) r += d[i]; } return r.trim(); };
const p = $('Clasificar y decidir').first().json;
const chatId = p.chatId; const category = p.category; const query = stripAccents(p.query);
let rows = $input.all().map(i => i.json).filter(r => r && r.id);
const STATUS = { unknown: 'Estado desconocido', ok: 'A salvo', injured: 'Herida', medical_attention: 'En atencion medica', transferred: 'Trasladada', with_family: 'Con su familia' };
const loc = (a, b) => [a, b].filter(Boolean).join(' - ');
let text = '';
if (category === 'persons') {
  if (query) { const words = query.split(' ').filter(Boolean); rows = rows.filter(r => { const name = stripAccents((r.first_name || '') + ' ' + (r.last_name || '')); if (name.indexOf(query) !== -1) return true; return words.every(w => name.indexOf(w) !== -1); }); }
  rows = rows.slice(0, 5);
  if (!rows.length) text = 'No encontre a <b>' + esc(p.query) + '</b> en los registros de NODO.' + NL + NL + 'Proba con otra forma del nombre. Escribe menu para volver.';
  else { text = '<b>Resultados</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { const e = r.is_found ? 'Encontrada' : 'Desaparecida'; const st = STATUS[r.current_status] || ''; text += '<b>' + esc((r.first_name || '') + ' ' + (r.last_name || '')) + '</b>' + NL; text += e + (st ? ' - ' + esc(st) : '') + NL; const l = loc(r.city, r.last_known_address); if (l) text += 'Ubicacion: ' + esc(l) + NL; text += NL; } text += '<i>Info de NODO (nodoayuda.com). Verifica por canales oficiales.</i>'; }
} else if (category === 'shelters') {
  rows = rows.slice(0, 8); if (!rows.length) text = 'No hay refugios activos registrados ahora mismo.';
  else { text = '<b>Refugios activos</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { text += '<b>' + esc(r.name) + '</b>' + NL; const l = loc(r.address_text, r.city); if (l) text += 'Ubicacion: ' + esc(l) + NL; if (r.capacity != null) text += 'Cupo: ' + esc(r.current_occupancy == null ? 0 : r.current_occupancy) + '/' + esc(r.capacity) + NL; text += NL; } }
} else if (category === 'hospitals') {
  rows = rows.slice(0, 8); if (!rows.length) text = 'No hay hospitales o centros medicos registrados.';
  else { text = '<b>Hospitales y centros medicos</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { text += '<b>' + esc(r.name) + '</b>' + NL; const l = loc(r.address_text, r.city); if (l) text += 'Ubicacion: ' + esc(l) + NL; text += NL; } }
} else if (category === 'health') {
  const bt = stripAccents(p.query);
  if (bt) rows = rows.filter(r => { const m = r.metadata || {}; const v = stripAccents(m.blood_type || ''); return v === bt; });
  rows = rows.slice(0, 8); if (!rows.length) text = 'No hay solicitudes de sangre' + (p.query ? (' tipo ' + esc(p.query)) : '') + ' ahora mismo.';
  else { text = '<b>Solicitudes de sangre</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { const m = r.metadata || {}; const h = m.hospital_name || r.name || 'Solicitud'; text += '<b>' + esc(h) + '</b>' + NL; if (m.blood_type) text += 'Tipo: ' + esc(m.blood_type) + NL; const l = loc(r.address_text, r.city); if (l) text += 'Ubicacion: ' + esc(l) + NL; text += NL; } }
} else if (category === 'acopio') {
  rows = rows.slice(0, 8); if (!rows.length) text = 'No hay centros de acopio registrados ahora mismo.';
  else { text = '<b>Centros de acopio</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { text += '<b>' + esc(r.name) + '</b>' + NL; const l = loc(r.address_text, r.city); if (l) text += 'Ubicacion: ' + esc(l) + NL; text += NL; } }
} else if (category === 'campaigns') {
  rows = rows.slice(0, 8); if (!rows.length) text = 'No hay campanas activas ahora mismo.';
  else { text = '<b>Campanas activas</b> (' + rows.length + '):' + NL + NL; for (const r of rows) { text += '<b>' + esc(r.title) + '</b>' + NL; if (r.organization) text += esc(r.organization) + NL; text += NL; } }
} else if (category === 'info') {
  rows = rows.slice(0, 6); if (!rows.length) text = 'No hay informacion verificada publicada ahora mismo.';
  else { text = '<b>Informacion verificada</b>:' + NL + NL; for (const r of rows) { text += '<b>' + esc(r.title) + '</b>' + NL; if (r.content) text += esc(String(r.content).slice(0, 200)) + NL; if (r.source) text += 'Fuente: ' + esc(r.source) + NL; text += NL; } }
} else { text = 'No encontre resultados.'; }
return [{ json: { chatId: chatId, replyText: text } }];
